"""Paper backup controls mounted once so polling never discards transcription drafts."""
BACKUP_JS = r"""
function backupTeacher(box){
  var details=el('details',{},el('summary',{text:'纸质备用与课后补录'})),message=el('p',{class:'notice'}),download=el('button',{text:'下载本课堂备用教学包（ZIP）'}),state=null,activeStudent='',activeQuestion='';
  box.appendChild(details);details.appendChild(el('p',{text:'课前解压并打印教师稿、学生练习、参考答案和记录卡。故障时按环节／页码／题号接续；恢复联网后按原课堂补录，核对后再结算。'}));details.appendChild(download);details.appendChild(message);
  var version=el('input',{placeholder:'纸质记录卡上的16位版本号',maxlength:'16',autocapitalize:'none',autocorrect:'off',spellcheck:'false'}),pupils=el('select'),questions=el('select'),stem=el('pre',{style:'white-space:pre-wrap'}),choice=el('select'),text=el('textarea',{placeholder:'原答案文字（也可上传答卷照片）'}),photo=el('input',{type:'file',accept:'image/jpeg,image/png'}),result=el('select'),hint=el('select'),reason=el('input',{placeholder:'故障原因／纸质答卷编号'}),stage=el('select'),page=el('input',{type:'number',min:'1',value:'1'}),when=el('input',{type:'datetime-local'}),save=el('button',{text:'核对并补入原课堂',class:'primary'}),resume=el('button',{text:'恢复到所选环节／页码'}),finish=el('button',{text:'纸质课已完成：结束原课堂'});
  for(var i=0;i<4;i++)hint.appendChild(el('option',{value:i,text:i+'级提示'}));
  [['correct','正确'],['partial','部分正确'],['revise','需订正']].forEach(function(x){result.appendChild(el('option',{value:x[0],text:x[1]}))});
  ['到课与热身','知识点介绍','例题讲解','随堂练习','练习复盘','课堂互动','布置课后'].forEach(function(x,i){stage.appendChild(el('option',{value:i+1,text:(i+1)+'. '+x}))});stage.value='4';
  var local=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);when.value=local;
  [['纸质包版本',version],['学生',pupils],['原题',questions],['题目核对',stem],['所选选项',choice],['原答案',text],['答卷照片（最多3MB）',photo],['教师批改',result],['实际使用提示',hint],['实际作答时间',when],['原因／答卷编号',reason],['接续环节',stage],['课件页码（环节2／3）',page]].forEach(function(x){details.appendChild(el('label',{class:'field'},el('span',{text:x[0]}),x[1]))});
  details.appendChild(save);details.appendChild(resume);details.appendChild(finish);
  function selection(){if(!state)return null;for(var i=0;i<state.questions.length;i++){var q=state.questions[i];if(q.kind+':'+q.id===questions.value)return q}return null}
  function show(){var q=selection();if(!q)return;var oldChoice=choice.value,same=activeStudent===pupils.value&&activeQuestion===questions.value;activeStudent=pupils.value;activeQuestion=questions.value;stem.textContent=q.stem;choice.textContent='';choice.appendChild(el('option',{value:'',text:'请选择纸上所选选项'}));(q.options||[]).forEach(function(x,i){choice.appendChild(el('option',{value:i,text:String.fromCharCode(65+i)+'. '+x}))});if(same)choice.value=oldChoice;choice.hidden=q.kind!=='choice';text.hidden=photo.hidden=result.hidden=q.kind==='choice';var existing=state.recorded.some(function(a){return a.studentId===Number(pupils.value)&&a.kind===q.kind&&a.questionId===q.id});save.disabled=!!state.settled||existing||state.status!=='finished';message.textContent=state.status!=='finished'?'请先结束原课堂，再补录纸质答案；可用下方“纸质课已完成”按钮结束。':state.settled?'本课堂已结算，补录已锁定。':existing?'该生本题已有作答，已保留；请到原批改区域核对。':'请对照纸质记录卡核实版本、学生和原题，再保存。'}
  function load(){return api('/teacher/weekend/sessions/'+SID+'/backup').then(function(d){var oldStudent=pupils.value,oldQ=questions.value;state=d;pupils.textContent='';questions.textContent='';d.students.forEach(function(p){pupils.appendChild(el('option',{value:p.id,text:p.name+'（'+p.id+'）'}))});d.questions.forEach(function(q,i){questions.appendChild(el('option',{value:q.kind+':'+q.id,text:'第'+(i+1)+'题 · '+q.kind+':'+q.id}))});if(oldStudent)pupils.value=oldStudent;if(oldQ)questions.value=oldQ;show();return d})}
  details.addEventListener('toggle',function(){if(details.open&&!state)load().catch(function(e){message.textContent=e.message})});questions.onchange=pupils.onchange=function(){if((text.value||(photo.files&&photo.files.length)||choice.value!=='')&&!confirm('切换学生或题目将清空本条未保存答案，确定吗？')){pupils.value=activeStudent;questions.value=activeQuestion;return}text.value='';photo.value='';choice.value='';hint.value='0';result.value='correct';show()};
  download.onclick=function(){if(text.value||(photo.files&&photo.files.length)||choice.value!==''){message.textContent='请先保存或清空当前补录草稿，再下载备用包';return}var downloadedVersion='';download.disabled=true;message.textContent='正在生成备用包…';load().then(function(d){return fetch('/teacher/weekend/sessions/'+SID+'/backup.zip',{headers:{Authorization:'Bearer '+TOKEN},cache:'no-store'}).then(function(r){if(!r.ok)return r.json().then(function(x){throw Error(x.detail||'生成失败')});downloadedVersion=r.headers.get('X-Changying-Paper-Version')||d.version;return r.blob()}).then(function(blob){var url=URL.createObjectURL(blob),a=el('a',{href:url,download:'weekend-'+SID+'-paper-backup.zip'});document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},60000);version.value=downloadedVersion;message.textContent='已下载。请解压、逐份检查并打印；教师稿／答案只留给老师。图片题务必核对原文件。'})}).catch(function(e){message.textContent=e.message}).then(function(){download.disabled=false})};
  function photoData(){return new Promise(function(resolve,reject){var f=photo.files&&photo.files[0];if(!f){resolve(null);return}if(f.size>3*1024*1024){reject(Error('答卷照片不能超过3MB'));return}var reader=new FileReader();reader.onload=function(){resolve(String(reader.result).split(',')[1])};reader.onerror=function(){reject(Error('照片读取失败'))};reader.readAsDataURL(f)})}
  save.onclick=function(){var q=selection();if(!q)return;if(!/^[0-9a-f]{16}$/.test(version.value.trim().toLowerCase())||!reason.value.trim()||!when.value){message.textContent='请填写纸质包版本、原因和实际作答时间';return}if(q.kind==='choice'&&choice.value===''){message.textContent='请选择纸上所选选项';return}if(!confirm('确认学生、原题与纸质答卷一致？保存不会覆盖已有线上答案。'))return;var outcome='';var payload={version:version.value.trim().toLowerCase(),studentId:Number(pupils.value),kind:q.kind,questionId:q.id,selected:q.kind==='choice'?Number(choice.value):null,text:text.value,result:result.value,hintLevel:Number(hint.value),stage:Number(stage.value),note:reason.value.trim(),occurredAt:new Date(when.value).toISOString()};var fields=[pupils,questions,choice,text,photo,result,hint,version,reason,when,stage,page,save,resume,finish,download];fields.forEach(function(x){x.disabled=true});photoData().then(function(data){payload.photoBase64=q.kind==='written'?data:null;return api('/teacher/weekend/sessions/'+SID+'/backup-record',{json:payload})}).then(function(r){text.value='';photo.value='';return load().then(function(){outcome=r.message})}).catch(function(e){outcome=e.message}).then(function(){fields.forEach(function(x){x.disabled=false});if(state)show();if(outcome)message.textContent=outcome})};
  resume.onclick=function(){resume.disabled=true;load().then(function(d){if(d.status==='finished')throw Error('原课堂已结束，可补录，但不重开课堂');if(d.status==='planned')return api('/teacher/weekend/sessions/'+SID+'/start',{json:{}})}).then(function(){return api('/teacher/weekend/sessions/'+SID+'/goto',{json:{stage:Number(stage.value)}})}).then(function(){if(Number(stage.value)===2||Number(stage.value)===3)return api('/teacher/weekend/sessions/'+SID+'/slide',{json:{index:Math.max(0,Number(page.value||1)-1)}})}).then(function(){message.textContent='已回到原课堂所选环节；实际纸质用时请保留在记录卡。'}).catch(function(e){message.textContent=e.message}).then(function(){resume.disabled=false})};
  finish.onclick=function(){if(!confirm('确认整节课已在纸上完成？将结束原课堂；补录后仍需核对并结算积分。'))return;finish.disabled=true;api('/teacher/weekend/sessions/'+SID+'/finish',{json:{}}).then(function(){return load()}).then(function(){message.textContent='原课堂已结束，请补齐记录并使用原有积分结算。'}).catch(function(e){message.textContent=e.message}).then(function(){finish.disabled=false})};
}
"""
